import {worldSummary} from './trace.mjs';
import {localChatMarkup} from './local-chat.mjs';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const helpTexts={chat:'Ask the local coding model about this execution step. Each question receives a snapshot of the line, nearby code, values, addresses, and output. Load is optional and runs on your GPU, with no paid inference service. Replies can be wrong; check the simulator. Release model frees GPU memory; downloaded files can stay cached.',map:'See the whole learning path. Earlier groups introduce skills used by later groups. Choose a module to inspect its exercises.',goals:'Compare what the PDF explicitly says with our interpretation of what it teaches. The labels keep these two kinds of information separate.',exercises:'Each entry comes from your module. Select one to see its requirements, learning purpose, and matching concept demonstrations.',requirements:'These requirements summarize the assignment, including restrictions. Open the cited PDF page for the complete source wording.',purpose:'This is our interpretation of the skill the exercise develops. Connect it to what you already know before running the example.',connection:'See which earlier ideas this exercise builds on and why the new skill is useful.',observe:'Use this guidance to decide which values, addresses, or state changes deserve attention in the example.',example:'Choose a small concept demonstration. It may isolate one part of the assignment and may use helpers outside the submission restrictions.',controls:'Advance one operation, go back, reset, or seek a step. Play is optional and stops at the end. All views share the same position.',code:'Read the highlighted source line. The snapshot shows the result after that operation; Back restores the earlier operation.',memory:'Look here to see what each variable stores and which memory contents change after this step. Blue marks changes; amber marks reads.',workspace:'Inspect file, Git, build, or linked-structure state. Compare names, contents, connections, and metadata after each operation.',inspector:'Select an object to distinguish its own storage address from its stored value. For a pointer, follow its target to see the next object.',graph:'Arrows connect a pointer to the object at its stored address. Follow one arrow per dereference; changing data does not necessarily move a pointer.',calls:'The last call is active. Earlier calls are waiting. Parameters and local objects belong to their own call and disappear when it returns.',companion:'This description belongs to the same highlighted operation as the state and output. Read why it happens, then check what to observe.',transfer:'Follow what is copied or accessed: an integer value, a character, an address, or output text. Assignment copies a value; dereferencing reaches an object.',changes:'Compare this operation’s previous snapshot with its current snapshot. A read or check may produce no stored-value change.',terminal:'Only output operations add visible text. Seeking backward restores earlier output. No output does not mean no work happened.',notes:'Write your own explanation or a question for this exercise. Notes are saved only in this browser, independently for each exercise.',rules:'Review core C meanings when a symbol is unfamiliar. Use the current code and memory view to make the rule concrete.',sources:'Open the original PDF at the referenced page. Source notes flag ambiguity instead of silently inventing requirements.',path:'This is your exact Modules or Rushes location. The sidebar keeps the hierarchy and numeric order you requested.'};
export const help=(key,label)=>`<button class="context-help" type="button" data-help="${key}" aria-label="Help: ${esc(label)}" aria-describedby="contextTip" aria-expanded="false">?</button>`;
const list=a=>`<ul>${(a||[]).map(s=>`<li>${esc(typeof s==='string'?s:JSON.stringify(s))}</li>`).join('')}</ul>`;
export function sourceLink(module,page=1,label='Open source PDF'){return `<a class="source-link" href="./sources/${module.source}#page=${page}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;}
export function moduleMarkup(module,exercise,catalog){
 const sims=exercise.simulations.map(id=>catalog.find(s=>s.id===id));
 return `<section class="lesson-header"><div><div class="breadcrumb">${esc(module.group==='rushes'?'Rushes':'Modules')} / ${esc(module.group)}</div><h1>${esc(module.title)} ${help('path','Module location')}</h1><p>${esc(module.summary)}</p><code class="module-path">${esc(module.path)}</code></div><div class="header-symbol" aria-hidden="true">&amp;<span>*</span></div></section>
 <details class="module-guide" open><summary><span>Module learning goals ${help('goals','Module learning goals')}</span><span class="summary-hint">Source + interpretation</span></summary><div class="goal-columns"><div><span class="source-label">EXPLICITLY STATED IN THE PDF</span>${module.statedGoals.length?list(module.statedGoals.map(g=>`${g.text} (PDF p. ${g.page})`)):'<p>No separate learning aim is explicitly stated. Use the assignment requirements as the direct source evidence.</p>'}</div><div><span class="interpret-label">OUR INTERPRETATION</span><p>${esc(module.interpretation)}</p><p><strong>Why it matters:</strong> ${esc(module.why)}</p><p><strong>Builds on:</strong> ${esc(module.prerequisites.join(' · '))}</p></div></div><div class="module-source">${sourceLink(module)} <span>${module.exercises.length} learning entries</span></div>${module.sourceNotes?.length?`<details class="source-notes"><summary>Source notes &amp; ambiguities ${help('sources','Source notes')}</summary>${list(module.sourceNotes)}</details>`:''}</details>
 <section class="exercise-nav"><div><h2>Exercises &amp; tutorial stages ${help('exercises','Exercises')}</h2><p>Choose an entry to reveal its goal and demonstrations.</p></div><label class="sr-only" for="exerciseSelect">Exercise</label><select id="exerciseSelect">${module.exercises.map(e=>`<option value="${esc(e.id)}" ${e.id===exercise.id?'selected':''}>${esc(e.id)} · ${esc(e.title)}</option>`).join('')}</select></section>
 <section class="exercise-card"><div class="exercise-top"><div><span class="exercise-id">${esc(exercise.id)}</span><h2>${esc(exercise.title)} ${help('requirements','Assignment requirements')}</h2></div>${sourceLink(module,exercise.page,`PDF p. ${exercise.page}`)}</div><div class="concept-chips">${exercise.concepts.map(c=>`<span>${esc(c)}</span>`).join('')}</div><div class="exercise-columns"><div><h3>What the assignment asks ${help('requirements','Assignment requirements')}</h3>${list(exercise.requirements)}</div><div><h3>What this teaches · interpretation ${help('purpose','Interpreted learning goal')}</h3><p>${esc(exercise.goal)}</p><h3>How it connects ${help('connection','Connections')}</h3><p>${esc(exercise.connection)}</p><h3>What to look for ${help('observe','Observation guidance')}</h3><p>${esc(exercise.observe)}</p></div></div></section>
 <details class="all-goals"><summary>See every exercise goal in this module ${help('exercises','All exercise goals')}</summary><div class="table-scroll"><table><thead><tr><th>Entry</th><th>Goal · interpretation</th><th>Source</th></tr></thead><tbody>${module.exercises.map(e=>`<tr><td><button data-exercise="${esc(e.id)}">${esc(e.id)} · ${esc(e.title)}</button></td><td>${esc(e.goal)}</td><td>${sourceLink(module,e.page,'p. '+e.page)}</td></tr>`).join('')}</tbody></table></div></details>
 <section class="example-picker"><div><h2>Concept demonstrations ${help('example','Concept demonstrations')}</h2><p>Complete runnable examples teach the mechanism. Read the exercise’s restrictions before writing your own submission.</p></div><label class="sr-only" for="simulationSelect">Concept demonstration</label><select id="simulationSelect">${sims.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></section>
 <div id="simulationIntro" class="simulation-intro"></div>
 <section class="transport" aria-label="Simulation controls"><div class="transport-buttons"><button id="prev" class="button">← Back</button><button id="next" class="button primary">Next step →</button><button id="play" class="button" aria-pressed="false">▷ Play</button><button id="reset" class="reset-button">↺ <span>Reset</span></button>${help('controls','Simulation controls')}</div><div class="step-position"><span id="stepLabel"></span><label class="speed-label">Pace<select id="speed" aria-label="Automatic step duration"><option value="4000">4s · slow</option><option value="2500">2.5s</option><option value="1500">1.5s</option></select></label></div><label class="sr-only" for="timeline">Execution timeline</label><input id="timeline" type="range" min="0" max="1" value="0"><div class="timeline-labels"><span>Start</span><span id="operationCount"></span><span>Finish</span></div></section>
 <div class="lab-grid"><section class="panel code-panel"><div class="panel-heading"><h2>Source code ${help('code','Source code')}</h2><span id="fileName" class="file-badge"></span></div><div class="code-caption"><span id="sourceKind"></span> · <span id="scopeLabel"></span></div><div id="code" class="code"></div><div class="code-foot"><span class="live-dot"></span><span id="lineLabel"></span></div></section>
 <section class="panel memory-panel"><div class="panel-heading"><h2 id="memoryHeading">State &amp; memory ${help('memory','Memory')}</h2><span class="small-label">TEACHING MODEL</span></div><div class="legend"><span><i class="legend-square write"></i>Changed</span><span><i class="legend-square read"></i>Read</span><span>Tap a cell to inspect</span></div><div id="world" class="world"></div><div id="memory" class="memory"></div><div class="inspect-label">Object inspector ${help('inspector','Object inspector')}</div><div id="inspector" class="inspector"></div><div class="connections"><div class="connection-heading"><h3>Follow the address ${help('graph','Pointer connections')}</h3></div><div id="graph"></div></div><div class="calls-panel"><h3>Function calls ${help('calls','Function calls')}</h3><div id="calls"></div></div></section>
 <section class="panel coach-panel"><div class="panel-heading"><h2>Step companion ${help('companion','Step companion')}</h2><span id="eventBadge" class="event-badge"></span></div><div class="coach-content" aria-live="polite" aria-atomic="true"><div class="step-eyebrow" id="coachStep"></div><h3 id="stepTitle"></h3><p id="what" class="what"></p><div class="flow-block"><span class="eyebrow">VALUE &amp; ADDRESS TRANSFER ${help('transfer','Value and address transfer')}</span><p id="flow"></p></div><div class="observe-block"><span class="observe-icon" aria-hidden="true">◎</span><div><h4>What to observe ${help('observe','What to observe')}</h4><p id="observe"></p></div></div><div class="change-heading"><h4>Before → After ${help('changes','Before and after')}</h4><span id="changeCount"></span></div><div id="changes" class="changes"></div></div></section></div>
 <section class="panel terminal-panel"><div class="panel-heading"><h2><span class="terminal-symbol">&gt;_</span>Terminal output ${help('terminal','Terminal output')}</h2><span id="terminalStatus" class="small-label"></span></div><div class="terminal-body"><span id="terminalPrompt" class="terminal-prompt"></span><pre id="terminal"></pre><span id="terminalEmpty" class="terminal-empty">No output yet. Operations can change state without printing.</span></div></section>
 ${localChatMarkup(help('chat','Local coding chat'))}
 <div class="bottom-grid"><details class="notes-card"><summary><span>✎ My learning notes ${help('notes','Learning notes')}</span><span class="summary-hint">Saved in this browser</span></summary><label for="notes">Explain the idea in your own words, or record a question.</label><textarea id="notes" rows="4" placeholder="What changed? Which value or address was copied? Why?"></textarea><span id="notesStatus" class="small-label"></span></details><details class="notes-card"><summary><span>{ } C field guide ${help('rules','C field guide')}</span></summary><dl><dt><code>&amp;x</code></dt><dd>The address of object x.</dd><dt><code>p</code></dt><dd>The address value stored in a pointer.</dd><dt><code>*p</code></dt><dd>The object reached by following p.</dd><dt><code>&amp;p</code></dt><dd>The address of the pointer object itself.</dd><dt><code>tab[i]</code></dt><dd>The same element as *(tab + i).</dd><dt><code>p + 1</code></dt><dd>The next element of the pointed type.</dd><dt><code>\\0</code></dt><dd>A zero character terminating a C string.</dd><dt><code>NULL</code></dt><dd>A null pointer referring to no object.</dd></dl><p>C passes arguments by value, including address values. A copied address may still reach a caller-owned object.</p><p>Addresses are invented for clarity. The int-array examples use 4-byte ints; real pointer arithmetic follows sizeof the pointed type. Only initialized, live, correctly typed targets may be dereferenced.</p></details></div>`;
}
export function worldMarkup(w){if(!w)return '';const heading=`<div class="world-heading">${w.kind==='board'?'Board / position':w.kind==='list'?'Linked nodes':w.kind==='tree'?'Tree nodes':'Workspace'} ${help('workspace','Workspace and structure')}</div>`;
 if(w.kind==='files')return heading+`<p class="world-caption">Current directory: <code>${esc(w.cwd)}</code></p>`+w.files.map(f=>`<div class="file-object"><strong>${esc(f.name)}</strong><small>${esc(f.kind)} ${esc(f.mode||'')}${f.inode?' · object '+esc(f.inode):''}</small><pre>${esc(f.content)}</pre>${f.target?`<span>→ ${esc(f.target)}</span>`:''}</div>`).join('')+(w.handles?`<p class="world-caption">${w.handles.map(h=>`fd ${h.fd}: ${esc(h.status)} · ${esc(h.file)}`).join(' · ')}</p>`:'');
 if(w.kind==='git')return heading+`<div class="git-stages">${[['work','Working tree'],['index','Index'],['commit','Commit'],['remote','Remote']].map(([k,n])=>`<div><small>${n}</small><strong>${esc(w[k])}</strong></div>`).join('')}</div>`;
 if(w.kind==='build')return heading+`<div class="build-phase">${esc(w.phase)}</div><div class="build-items">${w.items.map(i=>`<code>${esc(i)}</code>`).join('')}</div>`;
 if(w.kind==='board')return heading+`<div class="board">${w.rows.map((r,ri)=>`<div class="board-row">${r.map((v,ci)=>`<span class="board-cell ${w.current?.[0]===ri&&w.current?.[1]===ci?'current':''}">${v===0?'·':esc(v)}</span>`).join('')}</div>`).join('')}</div>`;
 if(w.kind==='list')return heading+`<p class="world-caption">Head / reversed prefix: ${esc(w.head||'NULL')}</p><div class="node-list">${w.nodes.map(n=>`<div class="linked-node"><strong>${esc(n.id)} <span>${esc(n.data)}</span></strong><small>${esc(n.address)}</small><div>next → ${esc(n.next||'NULL')}</div></div>`).join('')}</div>`;
 if(w.kind==='tree')return heading+`<p class="world-caption">Root: ${esc(w.root)}</p><div class="tree-layout">${w.nodes.map(n=>`<div class="linked-node ${n.id===w.root?'tree-root':''}"><strong>${esc(n.id)} <span>${esc(n.data)}</span></strong><small>${esc(n.address)}</small><div>L → ${esc(n.left||'NULL')}<br>R → ${esc(n.right||'NULL')}</div></div>`).join('')}</div>`;
 return heading+`<p>${esc(worldSummary(w))}</p>`;
}
